<script setup lang="ts">import { onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import AppPage from '../../components/common/AppPage.vue'; import StatusBadge from '../../components/common/StatusBadge.vue'; import EmptyState from '../../components/common/EmptyState.vue'; import ErrorState from '../../components/common/ErrorState.vue'; import { getPendingReviews } from '../../api/case'; import type { MedicalCase } from '../../types/case'; import { formatDateTime, waitingDuration } from '../../utils/format'; import { specialtyLabel } from '../../utils/medical'; const router = useRouter(); const items = ref<MedicalCase[]>([]); const loading = ref(true); const error = ref(''); async function load() { loading.value = true; try { items.value = (await getPendingReviews()).items } catch { error.value = '待审核队列加载失败' } finally { loading.value = false } } onMounted(load)</script>
<template><AppPage title="我的审核" description="高风险优先；相同风险下等待最久的病例排在前面"><el-skeleton v-if="loading" :rows="8" animated /><ErrorState v-else-if="error" :message="error" @retry="load" /><EmptyState v-else-if="!items.length" class="surface" title="当前没有待审核病例" description="新的 AI 辅助意见完成后会进入此队列" /><section v-else class="review-list"><article v-for="item in items" :key="item.id" class="surface review-item"><StatusBadge type="risk" :value="item.risk_level" /><div class="case-info"><span class="mono">{{ item.id }}</span><h2>{{ item.patient_name }}</h2><p>{{ item.question }}</p><small>{{ specialtyLabel(item.specialty) }}专业分析 · AI 完成于 {{ formatDateTime(item.ai_completed_at) }}</small></div><div class="waiting"><span>已等待</span><strong>{{ waitingDuration(item.ai_completed_at) }}</strong></div><el-button type="primary" @click="router.push(`/cases/${item.id}`)">立即审核</el-button></article></section></AppPage></template>
<style scoped lang="scss">.review-list { display: grid; gap: 12px; }.review-item { display: grid; grid-template-columns: 100px 1fr 110px auto; gap: 18px; align-items: center; padding: 18px 20px; }.case-info { min-width: 0; }.case-info .mono { color: var(--text-tertiary); font-size: 10px; }.case-info h2 { margin: 5px 0; font-size: 15px; }.case-info p { margin: 0 0 7px; color: var(--text-secondary); font-size: 12px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }.case-info small { color: var(--text-tertiary); }.waiting { display: grid; gap: 4px; }.waiting span { color: var(--text-tertiary); font-size: 10px; }.waiting strong { color: var(--risk-medium); font-size: 13px; }@media(max-width: 760px) { .review-item { grid-template-columns: 90px 1fr; }.waiting { display: none; }.review-item .el-button { grid-column: 2; } }</style>
